function dir$s23(p){
  this.constructor(p);
}
dir$s23.prototype = new DirEvent();
dir$s23.prototype.beforeInit = function(){
  var p = this._dir;
  if (p.options.action == 'EDIT') {
    p.field('ma_ct').disabled = true;
    p.field('username').disabled = true;
  }
}
dir$s23.prototype.afterInit = function(){
  var p = this._dir;
  p.options.dataChanged = true;
}
dir$s23.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'ma_ct':
      p.reloadGrid(0, ['ma_ct', 'C', v]);
      break;
    default:
      break;
  }
}
dir$s23.prototype = new DirEvent();
dir$s23.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
}
dir$s23.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid()
  p.options.dataChanged = true;


  dir$s23DisabledMasterField(p, g);
  dir$s23HiddenColumnByType(p);
  dir$s23HiddenColumnByTran(p);
  dir$s23HiddenColumnByComboBox(p);
  dir$s23DisabledStatusByAction(p);
}


