    case 'ok':
		if (p.valForm('den_ngay') <= p.valForm('tu_ngay')) { 
			<!-- $.question('jkhj '+'Nhap sai ngay ??' ); -->
			$.alert('Ngày hiệu lực đến không hợp lệ. Error Effective Date.');
			return false;
			Break;
			}
    default:
      break;
  }
  return true;
}
dir$s23.prototype.beforeButtonGridClick = function (id, gindex) {
var p = this._dir;
  switch (id) {
    case 'refresh':
      dir$s23LoadFieldGrid(p, 0);
      return false;
    default:
      break;
  }
  return true;
}
